import {samples} from './samples.js?v=20261027-inputs';
import {encodeRules,decodeRules,xIntentURL} from './sharing.js?v=20261027-inputs';
import{Machine,defaults,validate,parseCSV,csv}from './engine.js';
const $=id=>document.getElementById(id);let m=new Machine(),rules=structuredClone(defaults),running=false,timer=null,center=0,following=true;const key='turing-lab-v1';let firstVisit=true,shared=false,loadError='',renderedCenter=null,tapeAnimation=null;
try{const s=JSON.parse(localStorage.getItem(key));if(s&&Array.isArray(s.rules)&&!validate(s.rules)&&Array.isArray(s.tape)&&Number.isSafeInteger(s.head)&&typeof s.state==='string'){firstVisit=false;rules=s.rules;m.tape=new Map(s.tape);m.head=s.head;m.state=s.state;m.steps=s.steps||0;center=m.head;}}catch{}
function loadShared(){const params=new URLSearchParams(location.hash.slice(1));if(!params.has('rules'))return false;try{rules=decodeRules(params.get('rules'));m=new Machine();following=true;center=0;shared=true;return true;}catch(e){loadError='共有URLを読み込めません：'+e.message;return false;}}
loadShared();
function save(){try{localStorage.setItem(key,JSON.stringify({rules,tape:[...m.tape],head:m.head,state:m.state,steps:m.steps}));}catch{$('saveStatus').textContent='保存できません · このタブで利用可能';}}
function say(t){$('message').textContent=t;}
function edited(){$('shareBox').hidden=true;m.history=[];save();say('編集を保存しました。戻る履歴を消去しました。');update(false);}
function renderTape(){if(following)center=m.head;const delta=renderedCenter===null?0:center-renderedCenter;renderedCenter=center;tapeAnimation?.cancel();const count=Math.ceil(Math.min(window.innerWidth,1240)/70)+14;const half=Math.floor(count/2);$('tape').replaceChildren();for(let p=center-half;p<=center+half;p++){let d=document.createElement('div');d.className='cell'+(p===m.head?' head':'');let input=document.createElement('input');input.value=m.tape.get(p)||'';input.placeholder='□';input.setAttribute('aria-label',`テープ位置 ${p}`);input.disabled=running;input.addEventListener('input',()=>{if([...input.value].length>1){say('テープの記号は1文字で入力してください。');input.value=m.tape.get(p)||'';return;}if(input.value)m.tape.set(p,input.value);else m.tape.delete(p);edited();});let label=document.createElement('label');label.textContent=p;d.append(input,label);$('tape').append(d);} if(delta&&!matchMedia('(prefers-reduced-motion: reduce)').matches){tapeAnimation=$('tape').animate([{transform:`translateX(calc(-50% + ${delta*70}px))`},{transform:'translateX(-50%)'}],{duration:420,easing:'cubic-bezier(.22,.65,.3,1)'});} document.querySelector('.pointer').style.visibility=center===m.head?'visible':'hidden';document.querySelector('.neck').style.visibility=center===m.head?'visible':'hidden';$('follow').textContent=following?'◎ ヘッドを追従':'◎ ヘッドに戻る';}
function renderRules(){ $('rules').replaceChildren();rules.forEach((r,i)=>{let tr=document.createElement('tr');let n=document.createElement('td');n.textContent=String(i+1).padStart(2,'0');tr.append(n);r.forEach((v,j)=>{let td=document.createElement('td'),el=document.createElement(j===3?'select':'input');if(j===3){for(const [value,label]of[['L','← L'],['R','R →'],['S','· S']]){const o=new Option(label,value);el.add(o);}}el.value=v;if(j===1||j===2)el.placeholder='□';el.disabled=running;el.setAttribute('aria-label',`規則 ${i+1} ${['現在の状態','読み取り','書き込み','移動','次の状態'][j]}`);el.addEventListener(j===3?'change':'input',()=>{r[j]=el.value;edited();});td.append(el);tr.append(td);});let td=document.createElement('td'),del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',`規則 ${i+1} を削除`);del.disabled=running;del.onclick=()=>{rules.splice(i,1);renderRules();edited();};td.append(del);tr.append(td);$('rules').append(tr);});$('ruleCount').textContent=rules.length+' RULES';}
function update(refreshTape=true){const error=validate(rules);$('validation').textContent=error;$('share').disabled=!!error;$('shareX').disabled=!!error;document.querySelectorAll('#samples button,#samples input').forEach(b=>b.disabled=running);$('steps').textContent=String(m.steps).padStart(4,'0');$('state').textContent=m.state;$('reading').textContent=m.read()||'□';$('position').textContent=m.head;$('status').textContent=running?'実行中':!error&&!rules.some(r=>r[0]===m.state&&r[1]===m.read())?'計算停止':'一時停止';$('play').textContent=running?'Ⅱ 停止':'▶ 再生';$('play').disabled=!running&&!!error;$('next').disabled=running||!!error;$('back').disabled=running||!m.history.length;for(const id of['reset','add','import','export'])$(id).disabled=running;document.querySelectorAll('#rules input,#rules select,#rules button').forEach(el=>el.disabled=running);[...$('rules').children].forEach((tr,i)=>tr.classList.toggle('active',!error&&rules[i][0]===m.state&&rules[i][1]===m.read()));if(refreshTape)renderTape();}
function stop(){running=false;clearInterval(timer);timer=null;update();}
function step(){if(validate(rules))return;const oldHead=m.head;if(!m.step(rules)){stop();say(`状態「${m.state}」、記号「${m.read()||'□'}」に対応する規則がないため停止しました。`);return;}save();update();$('direction').textContent=m.head>oldHead?'ヘッド → 右へ':m.head<oldHead?'ヘッド ← 左へ':'ヘッド · 移動なし';say(`ステップ ${m.steps} · 状態 ${m.state} · ヘッド位置 ${m.head}`);if(!rules.some(r=>r[0]===m.state&&r[1]===m.read())){running=false;clearInterval(timer);timer=null;update(false);document.querySelectorAll('#tape input').forEach(el=>el.disabled=false);say(`計算停止：状態「${m.state}」、記号「${m.read()||'□'}」に対応する規則がありません。`);}}
function start(){if(validate(rules))return;if(!rules.some(r=>r[0]===m.state&&r[1]===m.read())){say('計算停止：現在の状態と記号に適用できる規則がありません。');update();return;}running=true;following=true;save();update();say('実行中 · 1秒ごとに1ステップ進みます。');clearInterval(timer);timer=setInterval(step,1000);}
$('play').onclick=()=>{if(running){stop();say('一時停止しました。テープと規則を編集できます。');}else{start();}};
$('next').onclick=()=>{following=true;step();};$('back').onclick=()=>{const oldHead=m.head;m.back();$('direction').textContent=m.head>oldHead?'ヘッド → 右へ':m.head<oldHead?'ヘッド ← 左へ':'ヘッド · 移動なし';following=true;save();update();say('1ステップ戻りました。');};$('reset').onclick=()=>{m=new Machine();following=true;renderedCenter=null;$('direction').textContent='ヘッド · 移動なし';save();update();say('空のテープ・位置 0・状態 start に戻しました。動作規則は保持しています。');};$('panLeft').onclick=()=>{following=false;center-=5;renderTape();};$('panRight').onclick=()=>{following=false;center+=5;renderTape();};$('follow').onclick=()=>{following=true;renderTape();};$('add').onclick=()=>{rules.push(['','','','S','']);renderRules();edited();$('rules').lastElementChild.scrollIntoView({block:'nearest'});};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const rs=parseCSV(await f.text());const err=validate(rs);if(err)throw Error(err);if(!rs.length)throw Error('CSV に規則がありません。');if(running)throw Error('停止してからインポートしてください。');rules=rs;renderRules();edited();say(`${rs.length} 件の動作規則をインポートしました。`);}catch(err){say('インポートできません：'+err.message);}e.target.value='';};$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([csv(rules)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='turing-rules.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say('動作規則を CSV にエクスポートしました。');};
$('share').onclick=()=>{try{const url=new URL(location.href);url.hash='rules='+encodeRules(rules);$('shareUrl').value=url.href;$('shareBox').hidden=false;$('shareFeedback').textContent='このURLには動作規則のみが含まれます。テープと実行履歴は含まれません。';$('shareUrl').focus();$('shareUrl').select();}catch(e){say(e.message);}};
$('copyShare').onclick=async()=>{try{await navigator.clipboard.writeText($('shareUrl').value);$('shareFeedback').textContent='共有URLをコピーしました。';}catch{$('shareUrl').focus();$('shareUrl').select();$('shareFeedback').textContent='URLを選択しました。コピーして共有してください。';}};
$('closeShare').onclick=()=>{$('shareBox').hidden=true;};
window.addEventListener('hashchange',()=>{stop();loadError='';shared=false;if(loadShared()){renderedCenter=null;renderRules();start();}else if(loadError)say(loadError);});

function ruleURL(){const url=new URL(location.href);url.hash='rules='+encodeRules(rules);return url.href;}
$('shareX').onclick=()=>{try{window.open(xIntentURL(ruleURL()),'_blank','noopener,noreferrer');}catch(e){say(e.message);}};
for(const sample of samples){
 const card=document.createElement('form');card.className='sample-card';
 const heading=document.createElement('h3');heading.textContent=sample.name;card.append(heading);
 const description=document.createElement('p');description.textContent=sample.description;card.append(description);
 const fields=(sample.fields||[]).map((field,i)=>{
  const label=document.createElement('label');label.textContent=field.label;
  const input=document.createElement('input');input.type='text';input.value=field.value;input.id=`sample-${sample.id}-${i}`;input.maxLength=128;input.autocomplete='off';input.spellcheck=false;input.placeholder=sample.id==='palindrome'?'空欄なら空列を判定':'例：101';label.htmlFor=input.id;
  card.append(label,input);return input;
 });
 const button=document.createElement('button');button.type='submit';button.textContent=sample.buildRules?'この入力で読み込む':'プログラムを読み込む';button.setAttribute('aria-label',sample.name+'を読み込む');card.append(button);
 card.onsubmit=e=>{
  e.preventDefault();if(running)return;let nextRules;const input=fields.map(f=>f.value.trim()).join(sample.id==='addition'?'+':'');
  try{nextRules=sample.buildRules?sample.buildRules(input):structuredClone(sample.rules);}catch(e){$('sampleInfo').textContent=e.message;return;}
  rules=nextRules;m=new Machine();following=true;center=0;renderedCenter=null;$('shareBox').hidden=true;$('direction').textContent='ヘッド · 移動なし';const url=new URL(location.href);url.hash='';history.replaceState(null,'',url);renderRules();save();update();
  $('sampleInfo').textContent=sample.buildRules?`入力 ${input||'空列'} を読み込みました。再生すると入力をテープに書き込み、その後に計算します。`:sample.description;
  say(`「${sample.name}」を読み込みました。再生またはステップ実行で開始します。`);
 };$('samples').append(card);
}

window.addEventListener('resize',()=>renderTape());renderRules();update();if(loadError)say(loadError);else if(firstVisit||shared)start();

